72	    public VectorStoreGenericDataModel<string> MapFromStorageToDataModel(JsonObject storageModel, StorageToDataModelMapperOptions options)
73	    {
74	        Verify.NotNull(storageModel);
75	
76	        // Create variables to store the response properties.
77	        var dataProperties = new Dictionary<string, object?>();
78	        var vectorProperties = new Dictionary<string, object?>();
79	        string? key = null;
80	
81	        // Loop through all known properties and map each from json to the data type.
82	        foreach (var property in this._vectorStoreRecordDefinition.Properties)
83	        {
84	            if (property is VectorStoreRecordKeyProperty keyProperty)
85	            {
86	                var storagePropertyName = keyProperty.StoragePropertyName ?? keyProperty.DataModelPropertyName;
87	                var value = storageModel[storagePropertyName];
88	                if (value is null)
89	                {
90	                    throw new InvalidOperationException($"The key property '{storagePropertyName}' is missing from the record retrieved from storage.");
91	                }
92	
93	                key = (string)value!;
94	            }
95	            else if (property is VectorStoreRecordDataProperty dataProperty)
96	            {
97	                var storagePropertyName = dataProperty.StoragePropertyName ?? dataProperty.DataModelPropertyName;
98	                var value = storageModel[storagePropertyName];
99	                if (value is not null)
100	                {
101	                    dataProperties.Add(dataProperty.DataModelPropertyName, GetDataPropertyValue(property.PropertyType, value));
102	                }
103	                else
104	                {
105	                    dataProperties.Add(dataProperty.DataModelPropertyName, null);
106	                }
107	            }
108	            else if (property is VectorStoreRecordVectorProperty vectorProperty && options.IncludeVectors)
109	            {
110	                var storagePropertyName = vectorProperty.StoragePropertyName ?? vectorProperty.DataModelPropertyName;
111	                var value = storageModel[storagePropertyName];
112	                if (value is not null)
113	                {
114	                    ReadOnlyMemory<float> vector = value.AsArray().Select(x => (float)x!).ToArray();
115	                    vectorProperties.Add(vectorProperty.DataModelPropertyName, vector);
116	                }
117	                else
118	                {
119	                    vectorProperties.Add(vectorProperty.DataModelPropertyName, null);
120	                }
121	            }
122	        }
123	
124	        if (key is null)
125	        {
126	            throw new InvalidOperationException("No key property was found in the record retrieved from storage.");
127	        }
128	
129	        return new VectorStoreGenericDataModel<string>(key) { Data = dataProperties, Vectors = vectorProperties };
130	    }
