aProperties.Add(dataProperty.DataModelPropertyName, null);\n                    }\n                }\n            }\n            else if (property is VectorStoreRecordVectorProperty vectorProperty && options.IncludeVectors)\n            {\n                // Just skip this property if it's not in the storage model.\n                if (storageModel.TryGetPropertyValue(vectorProperty.StoragePropertyName ?? vectorProperty.DataModelPropertyName, out var value))\n                {\n                    if (value is not null)\n                    {\n                        ReadOnlyMemory<float> vector = value.AsArray().Select(x => (float)x!).ToArray();\n                        vectorProperties.Add(vectorProperty.DataModelPropertyName, vector);\n                    }\n                    else\n                    {\n                        vectorProperties.Add(vectorProperty.DataModelPropertyName, null);\n                    }\n                }\n            }\n        }\n\n        if (key is null)\n        {\n            throw new InvalidOperationException(\"No key property was found in the record retrieved from storage.\");", "numLines": 62, "startLine": 71, "totalLines": 189}}
